-- Accept UTF-8 BOM without copying the entire file.
local firstByte = data:sub(1, 3) == "\239\187\191" and 4 or 1
if not data:sub(firstByte, firstByte + 100):match("^%d+:%s*%S") then
    notice("Invalid list format. Expected sorted lines such as 12345:1,2.")
    return
end
local localPlayer = Players.LocalPlayer
