local function status(phase, detail, progress)
    if not state.Active then return end
    phaseLabel.Text = phase
    detailLabel.Text = detail
    fill.Size = UDim2.fromScale(math.clamp(progress or 1, 0, 1), 1)
    local scanned, matched = 0, 0
    for _, entry in pairs(tracked) do
        scanned = scanned + 1
        if entry.country then matched = matched + 1 end
    end
    countLabel.Text = string.format("Online checked: %d   |   Matched: %d", scanned, matched)
end
-- Live detected-player list; entries are created/removed by player events.
