local collapse = Instance.new("TextButton")
collapse.Size = UDim2.fromOffset(28, 24)
collapse.Position = UDim2.new(1, -40, 0, 9)
collapse.BackgroundColor3 = Color3.fromRGB(37, 48, 67)
collapse.TextColor3 = Color3.fromRGB(231, 239, 255)
collapse.Text = "-"
collapse.TextSize = 18
collapse.Font = Enum.Font.GothamSemibold
collapse.Parent = panel
round(collapse, 6)
local collapsed = false
connections[#connections + 1] = collapse.Activated:Connect(function()
    collapsed = not collapsed
    list.Visible = not collapsed
    listTitle.Visible = not collapsed
    panel.Size = UDim2.fromOffset(300, collapsed and 132 or 432)
    collapse.Text = collapsed and "+" or "-"
    local matches = 0
    for _, entry in pairs(tracked) do if entry.country then matches = matches + 1 end end
    empty.Visible = not collapsed and matches == 0
end)
local function refreshDetected()
    if not state.Active then return end
    local matches = {}
    for player, entry in pairs(tracked) do
        if entry.country then matches[#matches + 1] = player end
    end
    table.sort(matches, function(a, b)
        local an, bn = a.Name:lower(), b.Name:lower()
        if an == bn then return a.UserId < b.UserId end
        return an < bn
    end)
    listTitle.Text = string.format("DETECTED PLAYERS (%d)", #matches)
    empty.Visible = not collapsed and #matches == 0
    for index, player in ipairs(matches) do
        local entry = tracked[player]
        if not entry.row then
            local row = Instance.new("Frame")
            row.Size = UDim2.new(1, -7, 0, 108)
            row.BackgroundColor3 = Color3.fromRGB(28, 36, 51)
            row.BorderSizePixel = 0
            row.Parent = list
            round(row, 8)
            entry.row = row
            local function rowLabel(y, height, size, text, color)
                local label = Instance.new("TextLabel")
                label.BackgroundTransparency = 1
                label.Position = UDim2.fromOffset(9, y)
                label.Size = UDim2.new(1, -84, 0, height)
                label.Font = Enum.Font.GothamSemibold
                label.TextSize = size
                label.TextColor3 = color
                label.TextXAlignment = Enum.TextXAlignment.Left
                label.TextYAlignment = Enum.TextYAlignment.Top
                label.TextWrapped = true
                label.Text = text
                label.Parent = row
            end
            rowLabel(9, 20, 13, player.DisplayName, Color3.fromRGB(231, 239, 255))
            rowLabel(30, 30, 10, "@" .. player.Name .. "\nID: " .. player.UserId, Color3.fromRGB(146, 163, 188))
            rowLabel(63, 40, 11, entry.country, Color3.fromRGB(132, 204, 255))
            local button = Instance.new("TextButton")
            button.Size = UDim2.fromOffset(58, 32)
            button.Position = UDim2.new(1, -67, 0, 38)
            button.BackgroundColor3 = Color3.fromRGB(56, 102, 156)
            button.TextColor3 = Color3.fromRGB(245, 249, 255)
            button.Font = Enum.Font.GothamSemibold
            button.TextSize = 12
            button.Text = player == localPlayer and "You" or "TP"
            button.AutoButtonColor = player ~= localPlayer
            button.Active = player ~= localPlayer
            button.Parent = row
            round(button, 7)
            entry.tpConnection = button.Activated:Connect(function()
                if not state.Active or player == localPlayer then return end
                if tracked[player] ~= entry or player.Parent ~= Players then
                    status("Player unavailable", "That player has left the server.", 1)
                    return
                end
                local mine, target = localPlayer.Character, player.Character
                local myRoot = mine and mine:FindFirstChild("HumanoidRootPart")
                local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
                local humanoid = mine and mine:FindFirstChildOfClass("Humanoid")
                if not myRoot or not targetRoot or not targetRoot:IsA("BasePart") or not humanoid or humanoid.Health <= 0 then
                    status("Teleport unavailable", "Wait for both characters to spawn or the target to load.", 1)
                    return
                end
                local success = pcall(function()
                    mine:PivotTo(targetRoot.CFrame * CFrame.new(4, 0, 0))
                end)
                status(success and "Teleport requested" or "Teleport failed",
                    success and ("Moved beside " .. player.DisplayName .. ". The server may reset movement.")
                    or "Character movement was unavailable. Try again after respawning.", 1)
            end)
        end
        entry.row.LayoutOrder = index
    end
end

status("Loading...", "Embedded list: 1,307,801 IDs / 15 countries. Preparing player scan.", 0)
task.wait() -- let the loading panel render before scanning

-- Binary search in the original sorted text. Only matched online players are
-- cached: no million-entry table, HTTP requests, or per-frame scan.
local function decodeCountries(codes)
    local names = {}
    for token in codes:gmatch("%d+") do
        local name = Countries[tonumber(token)]
        if name then names[#names + 1] = name end
    end
    return #names > 0 and table.concat(names, ", ") or nil
end
local function lookup(userId)
    if cache[userId] ~= nil then return cache[userId] or nil end
    local low, high = firstByte, #data
    while low <= high do
        local start = math.floor((low + high) / 2)
        while start > firstByte and data:byte(start - 1) ~= 10 do
            start = start - 1
        end
        local finish = data:find("\n", start, true) or (#data + 1)
        local id, countries = data:sub(start, finish - 1):match("^(%d+):%s*(.-)%s*$")
        id = tonumber(id)
        if not id then
            -- A trailing blank line is permitted; malformed interior rows aren't.
            if start >= #data then high = start - 1 else break end
        elseif id == userId then
            local decoded = decodeCountries(countries)
            cache[userId] = decoded or false
            return decoded
        elseif id < userId then
            low = finish + 1
        else
            high = start - 1
        end
    end
    cache[userId] = false
    return nil
end

local accents = {
    Sweden = Color3.fromRGB(100, 183, 255),
    Norway = Color3.fromRGB(255, 123, 139),
    Germany = Color3.fromRGB(255, 202, 103),
    France = Color3.fromRGB(137, 166, 255),
    Denmark = Color3.fromRGB(255, 132, 148),
    Netherlands = Color3.fromRGB(255, 171, 100),
    Poland = Color3.fromRGB(255, 159, 189),
    Russia = Color3.fromRGB(166, 186, 255),
    Finland = Color3.fromRGB(144, 207, 255),
    Spain = Color3.fromRGB(255, 211, 119),
    Romania = Color3.fromRGB(255, 208, 113),
    Italy = Color3.fromRGB(128, 226, 175),
    Greece = Color3.fromRGB(132, 204, 255),
    ["Türkiye"] = Color3.fromRGB(255, 138, 145),
    Brazil = Color3.fromRGB(160, 230, 125),
}
local function clearTag(entry)
    if entry.tag then entry.tag:Destroy(); entry.tag = nil end
end
local function attach(player, entry, character)
    clearTag(entry)
    entry.character = character
    if not entry.country then return end
    local function addHead(head)
        if not state.Active or tracked[player] ~= entry or entry.character ~= character then return end
        if not head:IsA("BasePart") or head.Name ~= "Head" then return end
        clearTag(entry)
        local country = entry.country
        local color = accents[country:match("^[^,]+") or country] or Color3.fromRGB(133, 213, 255)
        local measured = TextService:GetTextSize(country, 15, Enum.Font.GothamSemibold, Vector2.new(330, 1000))
        local width = math.clamp(measured.X + 30, 100, 360)
        local height = math.clamp(measured.Y + 18, 34, 110)
        local tag = Instance.new("BillboardGui")
        tag.Name = "Country_" .. player.UserId
        tag.Adornee = head
        tag.Size = UDim2.fromOffset(width, height)
        tag.StudsOffsetWorldSpace = Vector3.new(0, Config.Height, 0)
        tag.MaxDistance = Config.MaxDistance
        tag.AlwaysOnTop = false
        tag.LightInfluence = 0
        tag.ResetOnSpawn = false
        local panel = Instance.new("Frame")
        panel.Size = UDim2.fromScale(1, 1)
        panel.BackgroundColor3 = Color3.fromRGB(18, 23, 34)
        panel.BackgroundTransparency = 0.12
        panel.BorderSizePixel = 0
        panel.Parent = tag
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 10)
        corner.Parent = panel
        local stroke = Instance.new("UIStroke")
        stroke.Color = color
        stroke.Transparency = 0.35
        stroke.Thickness = 1
        stroke.Parent = panel
        local label = Instance.new("TextLabel")
        label.BackgroundTransparency = 1
        label.Position = UDim2.fromOffset(10, 5)
        label.Size = UDim2.new(1, -20, 1, -10)
        label.Text = country
        label.TextColor3 = color
        label.TextSize = 15
        label.Font = Enum.Font.GothamSemibold
        label.TextWrapped = true
        label.RichText = false
        label.Parent = panel
        tag.Parent = root
        entry.tag = tag
    end
    if entry.headConnection then entry.headConnection:Disconnect() end
    entry.headConnection = character.ChildAdded:Connect(addHead)
    local head = character:FindFirstChild("Head")
    if head then addHead(head) end
end
local function remove(player)
    local entry = tracked[player]
    if not entry then return end
    tracked[player] = nil
    if entry.tpConnection then entry.tpConnection:Disconnect() end
    if entry.row then entry.row:Destroy() end
    refreshDetected()
    if entry.spawnConnection then entry.spawnConnection:Disconnect() end
    if entry.removeConnection then entry.removeConnection:Disconnect() end
    if entry.headConnection then entry.headConnection:Disconnect() end
    clearTag(entry)
    if not initializing then status("Loaded - watching players", "Player left. Country tags are up to date.", 1) end
end
local function watch(player)
    if not state.Active or tracked[player] then return end
    if player == localPlayer and not Config.ShowSelf then return end
    if not initializing then
        status("Scanning player...", player.DisplayName .. " (@" .. player.Name .. ")", 0.5)
    end
    local entry = { country = lookup(player.UserId) }
    tracked[player] = entry
    refreshDetected()
    entry.spawnConnection = player.CharacterAdded:Connect(function(character)
        attach(player, entry, character)
    end)
    entry.removeConnection = player.CharacterRemoving:Connect(function(character)
        if entry.character == character then
            entry.character = nil
            if entry.headConnection then entry.headConnection:Disconnect(); entry.headConnection = nil end
            clearTag(entry)
        end
    end)
    if player.Character then attach(player, entry, player.Character) end
    if not initializing then
        local result = entry.country and ("Matched: " .. entry.country) or "No country match in the list."
        task.defer(function()
            if tracked[player] == entry then
                status("Loaded - watching players", player.DisplayName .. ": " .. result, 1)
            end
        end)
    end
end
function state.Stop()
    if not state.Active then return end
    state.Active = false
    for _, connection in ipairs(connections) do connection:Disconnect() end
    local players = {}
    for player in pairs(tracked) do players[#players + 1] = player end
    for _, player in ipairs(players) do remove(player) end
    root:Destroy()
    screen:Destroy()
    cache = {}
    data = nil
    if env.CountryTags == state then env.CountryTags = nil end
end
connections[#connections + 1] = Players.PlayerAdded:Connect(watch)
connections[#connections + 1] = Players.PlayerRemoving:Connect(remove)
local initialPlayers = Players:GetPlayers()
for index, player in ipairs(initialPlayers) do
    if not state.Active then break end
    status(string.format("Scanning players: %d / %d", index, #initialPlayers),
        player.DisplayName .. " (@" .. player.Name .. ")", (index - 1) / math.max(1, #initialPlayers))
    task.wait() -- visible, real progress; no recurring scan loop
    if state.Active and player.Parent == Players then watch(player) end
end
initializing = false
if state.Active then
    status("Loaded - watching players", "Scan complete. New players are checked automatically.", 1)
    notice("Loaded. Player scan complete; country tags are active.")
end
